const LNS={
'british-army':{n:'British Army',tag:'United Kingdom · Armed forces',
 d:'Who can apply, what the assessment centre tests, and how to prepare for British Army selection.',
 req:[
 ['Who can apply',['British citizens can apply. This includes British Overseas Territory citizens, British Overseas citizens, British subjects, British National (Overseas) citizens and British protected persons.','Irish citizens can apply to the regular Army.','Commonwealth citizens are recruited in set application windows. Check that a window is open before you start.','Refugees and asylum seekers cannot join.']],
 ['Age',['Age limits depend on the route: junior soldier, regular soldier, officer or reserve. Check the age shown for your chosen role before you apply.']],
 ['Education',['Many soldier roles do not ask for a set qualification. Reading, writing and number skills are tested instead at the assessment centre.','Some trades and officer routes do ask for specific qualifications.']],
 ['Health',['After you apply you complete an online medical questionnaire.','You must meet the Army medical standard for your role. Be honest and complete on every form.']],
 ['Fitness',['Fitness is tested at the assessment centre. The standard is higher for combat roles and different for junior soldiers.','The tests have included a timed 2 km run, a mid-thigh pull and a medicine ball throw.']]
 ],
 steps:[['Apply online','Choose a role and send your application.'],['Medical questionnaire','Answer the online health questions.'],['Army briefing','Attend a briefing at your local armed forces careers office.'],['Assessment centre','Fitness tests, reading and number tests, teamwork tasks and the Army Cognitive Test.'],['Offer and training','If you pass, you are offered a role and a start date for basic training.']],
 stepNote:'The order of the stages can vary by role.',
 prep:['Practise verbal, numerical and logical reasoning under time pressure. The practice questions on this site follow that pattern.','Build running and strength gradually. Rest between hard sessions.','Read about your chosen role so you can explain why you want it.','Practise working in a team and listening before you speak.']},
'french-foreign-legion':{n:'French Foreign Legion',tag:'France · Foreign Legion',
 d:'Age, papers, medical rules and the three selection phases of the French Foreign Legion.',
 req:[
 ['Age',['You must be over 17 and under 40 on the day you report to the information desk.','Candidates under 18 need extra documents, including permission signed by both parents or guardians and copies of their ID. Documents from foreign minors must be translated by an accredited French translator.']],
 ['Identity and papers',['Nationals of Schengen Area countries, Ireland, Cyprus, the United Kingdom, Monaco and Andorra need a national ID card and/or a passport, valid or not.','All other candidates need a passport, valid or not.','The Legion does not handle visas or exit permission.']],
 ['Education and language',['No school diploma is required.','You must be able to read and write in your mother tongue.']],
 ['Medical',['Your teeth must be healthy or treated, with a chewing coefficient of at least 40%.','Body mass index must be between 18 and 30.','Disqualifying conditions include a permanent physical impairment and an active chronic illness that is untreated or still under treatment. Vision or hearing that is too weak also disqualifies.','Bring your medical records, your health booklet if you have one, and your glasses if you wear them.']],
 ['Fitness',['You must be fit to serve anywhere, at any time, without restriction, and medically fit for the physical tests on the day you arrive.','Swimming at least 25 m without a float is strongly recommended. The swimming test does not eliminate you.']]
 ],
 steps:[['Evaluations (7 days)','At a preselection centre at Fontenay-sous-Bois or Aubagne: motivation interviews, sports tests, a first medical examination and signing of a five-year contract.'],['Selection (7 days)','At the selection centre in Aubagne: logic tests that need no school knowledge, another motivation interview, a security interview, another medical examination, a personality test and the selection board.'],['Incorporation (7 days)','Results are announced, formalities are completed and the contract is presented at the Legion museum.'],['Training','Recruits go to the 4th Foreign Regiment for four months of training before they join an operational regiment. The ten best-ranked candidates choose their regiment first.']],
 stepNote:'The tests as a whole take two to three weeks.',
 prep:['Practise logic and number questions. The psychotechnical tests need no school knowledge, only clear thinking.','Build running fitness and learn to swim 25 m.','Collect your papers and medical records before you travel.','Be ready to explain your motivation honestly in interviews.']},
'singapore-police-force':{n:'Singapore Police Force',tag:'Singapore · Police',
 d:'Entry routes, National Service status, vision rules and the four selection stages for Singapore Police Force officers.',
 req:[
 ['Entry routes',['Direct-Entry Sergeant: education is assessed against your academic qualifications.','Direct-Entry Inspector: a pass degree in any discipline.']],
 ['Citizenship',['Regular police officer roles are generally open to Singapore Citizens. Confirm the rule on the official application page before you apply.']],
 ['National Service',['Men need PES status A or B1. Women are exempted.','Pre-enlistees can serve five years as a regular police officer to fulfil their full-time National Service. They should apply three months before their enlistment date.']],
 ['Vision and health',['Normal colour vision is required.','You take a medical examination as the last selection stage.']],
 ['Training',['Residential training lasts six months and covers police contact tactics, physical training and criminal law.','After graduation, most officers start on the front line at a Neighbourhood Police Centre.']]
 ],
 steps:[['Tea session','An informal interview with the recruitment manager.'],['Panel interview','Two to three panellists ask about your motives, values and judgement.'],['Psychometric test','A computer test, taken if required.'],['Medical examination','A medical check with the medical partner.']],
 stepNote:'Shortlisted applicants are told by email within two weeks of applying.',
 prep:['Practise verbal, numerical and logical questions. The practice questions on this site follow that pattern.','Prepare short, honest answers about why you want to serve the public.','Practise situation questions: what you would do, and why.','Keep your fitness steady so training is not a shock.']}
};
