const lnE=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const lnRound=n=>Math.round(n/100)*100;
const lnPool=(id,c)=>LNB[id].filter(q=>c==null||q[0]===c);
const lnCatIx=s=>LNC.findIndex(c=>c[0]===s);
const lnSh=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const lnPick=(a,n)=>lnSh(a).slice(0,n);
const lnSpread=(a,n)=>{if(a.length<=n)return a.slice();const o=[],st=a.length/n;for(let i=0;i<n;i++)o.push(a[Math.floor(i*st)]);return o};
const lnSel=p=>LNS[p[1]]?p[1]:null;
function lnSeo(p){
 const id=lnSel(p),T=' — The Sujan Khadka';
 if(!p[1])return{title:'Selection Practice Tests and Requirements'+T,desc:'Free practice questions with answers and clear requirements for British Army, French Foreign Legion and Singapore Police Force selection.',crumbs:[['Learn','/learn']],
  ld:{'@context':'https://schema.org','@type':'ItemList',name:'Selection practice tests and requirements',itemListElement:LN_IDS.map((k,i)=>({'@type':'ListItem',position:i+1,name:LNS[k].n+' requirements and practice',url:location.origin+'/learn/'+k}))}};
 if(!id)return{title:'Learn'+T,desc:'',crumbs:[],noindex:true};
 const S=LNS[id],base='/learn/'+id,crumbs=[['Learn','/learn'],[S.n,base]],org={'@type':'Organization',name:'The Sujan Khadka',url:location.origin+'/',logo:location.origin+'/icon-192.png'};
 const art=(h,d,u)=>({'@context':'https://schema.org','@type':'Article',headline:h,description:d,datePublished:LN_DATE,dateModified:LN_DATE,author:{'@type':'Person',name:'Sujan Kumar Khadka'},publisher:org,mainEntityOfPage:location.origin+u,image:[location.origin+'/icon-512.png']});
 if(!p[2]){const t=S.n+' Requirements and Selection Stages',d='Who can apply, age, medical and fitness rules, selection stages and how to prepare for '+S.n+' selection. Plain language, free to read.';return{title:t+T,desc:d,crumbs,ld:art(t,d,base)}}
 if(p[2]!=='practice')return{title:'Learn'+T,desc:'',crumbs:[],noindex:true};
 crumbs.push(['Practice',base+'/practice']);
 const quiz=(name,pool)=>({'@context':'https://schema.org','@type':'Quiz',name,about:{'@type':'Thing',name:S.n+' selection'},educationalLevel:'Adult',hasPart:lnSpread(pool,5).map(q=>({'@type':'Question',eduQuestionType:'Multiple choice',name:q[1],text:q[1],suggestedAnswer:q[3].map((w,i)=>({'@type':'Answer',text:w,position:i+2})),acceptedAnswer:{'@type':'Answer',text:q[2],position:1,answerExplanation:{'@type':'Comment',text:q[4]}}}))});
 if(!p[3]){const t=S.n+' Practice Test: Free Questions and Answers',d='Free '+S.n+' selection practice questions with answers and explanations: verbal, numerical and logical reasoning, judgement and fitness. About '+lnRound(LNB[id].length).toLocaleString('en-US')+' questions.';return{title:t+T,desc:d,crumbs,ld:quiz(t,LNB[id])}}
 const ci=lnCatIx(p[3]);if(ci<0||p[4])return{title:'Learn'+T,desc:'',crumbs:[],noindex:true};
 const C=LNC[ci],t=S.n+' '+C[1]+' Practice Questions',d='Practise '+S.n+' '+C[1].toLowerCase()+' questions with instant answers and explanations. '+C[2]+'.';crumbs.push([C[1],base+'/practice/'+C[0]]);
 return{title:t+T,desc:d,crumbs,ld:quiz(t,lnPool(id,ci))};
}
