function lnStyle(){if(document.getElementById('lnstyle'))return;const s=document.createElement('style');s.id='lnstyle';s.textContent=`
#learn{--lb:#052962;--lt:#fff;--ok:#0a7a3d;--no:#c70000;--bx:rgba(0,0,0,.04);padding:8px 0 40px}
:root[data-theme=dark] #learn{--lb:#ffe500;--lt:#052962;--ok:#5fd38d;--no:#ff7f73;--bx:rgba(255,255,255,.07)}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]) #learn{--lb:#ffe500;--lt:#052962;--ok:#5fd38d;--no:#ff7f73;--bx:rgba(255,255,255,.07)}}
#learn a{color:inherit}
#learn .lp{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 14px;padding:0}
#learn .lp a,#learn .lp button{font:inherit;font-size:14px;font-weight:700;padding:8px 14px;border:1px solid var(--tx);border-radius:999px;background:none;color:var(--tx);text-decoration:none;cursor:pointer;line-height:1.2}
#learn .lp .on{background:var(--tx);color:var(--bg)}
#learn .lt{display:flex;gap:0;margin:0 0 20px;border-bottom:1px solid var(--ln)}
#learn .lt a{font-size:15px;font-weight:800;padding:10px 18px 9px;text-decoration:none;border-bottom:3px solid transparent;margin-bottom:-1px}
#learn .lt .on{border-bottom-color:var(--ac);color:var(--ac)}
#learn h2{font-size:22px;line-height:1.2;margin:26px 0 10px;padding-top:12px;border-top:3px solid var(--ac)}
#learn h2:first-of-type{margin-top:6px}
#learn h3{font-size:17px;margin:18px 0 6px}
#learn ul,#learn ol{margin:0 0 6px;padding-left:20px}
#learn li{margin:0 0 8px;line-height:1.5;font-size:16px}
#learn ol li b{display:block}
#learn p{line-height:1.55;margin:0 0 10px}
#learn .lm{color:var(--mu);font-size:14px}
#learn .lg{display:grid;gap:16px;grid-template-columns:1fr}
#learn .lc{border-top:3px solid var(--ac);padding:12px 0 6px}
#learn .lc small{display:block;font-size:12px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:var(--ac)}
#learn .lc h3{font-size:24px;margin:4px 0 6px}
#learn .lc .lk{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
#learn .lnb{display:inline-block;font:inherit;font-size:15px;font-weight:800;padding:11px 20px;border:2px solid var(--lb);border-radius:999px;background:var(--lb);color:var(--lt)!important;text-decoration:none;cursor:pointer;line-height:1.2}
#learn .lnb.o{background:none;color:var(--tx)!important;border-color:var(--tx)}
#learn .lnb[disabled]{opacity:.45;cursor:default}
#learn .ls{margin:0 0 14px}
#learn .ls b{display:block;font-size:13px;margin:0 0 6px;color:var(--mu);text-transform:uppercase;letter-spacing:.05em}
#learn .lr{margin:18px 0}
#learn .lnq{font-size:20px;line-height:1.35;font-weight:700;margin:6px 0 14px}
#learn .lh{display:flex;justify-content:space-between;font-size:14px;color:var(--mu);font-weight:700}
#learn .lbar{height:4px;background:var(--ln);margin:6px 0 4px}#learn .lbar i{display:block;height:100%;background:var(--ac)}
#learn .lo{display:block;width:100%;text-align:left;font:inherit;font-size:17px;padding:13px 14px;margin:0 0 9px;border:1px solid var(--ln);border-radius:10px;background:var(--bx);color:var(--tx);cursor:pointer;line-height:1.35}
#learn .lo span{font-weight:800;margin-right:10px}
#learn .lo.ok{border:2px solid var(--ok)}#learn .lo.no{border:2px solid var(--no)}
#learn .lo em{float:right;font-style:normal;font-weight:800}
#learn .lo.ok em{color:var(--ok)}#learn .lo.no em{color:var(--no)}
#learn .lx{border-left:4px solid var(--ac);padding:8px 12px;margin:12px 0;background:var(--bx);line-height:1.5}
#learn .lscore{font-size:44px;font-weight:800;line-height:1;margin:6px 0}
#learn details{border-top:1px solid var(--ln);padding:10px 0}
#learn summary{cursor:pointer;font-weight:700;line-height:1.4}
#learn details p{margin:8px 0 0}
#learn .lw{border-top:1px solid var(--ln);padding:12px 0}
@media(min-width:760px){#learn .lg{grid-template-columns:repeat(3,1fr)}}
`;document.head.appendChild(s)}
function lnPills(id,tab){return `<div class="lp" role="navigation" aria-label="Choose a selection">${LN_IDS.map(k=>`<a href="/learn/${k}${tab==='practice'?'/practice':''}" class="${k===id?'on':''}"${k===id?' aria-current="page"':''}>${lnE(LNS[k].n)}</a>`).join('')}</div>`}
function lnTabs(id,tab){return `<div class="lt" role="navigation" aria-label="${lnE(LNS[id].n)}"><a href="/learn/${id}" class="${tab==='req'?'on':''}">Requirements</a><a href="/learn/${id}/practice" class="${tab==='practice'?'on':''}">Practice questions</a></div>`}
function lnHub(){return `<div class="lg">${LN_IDS.map(k=>{const S=LNS[k];return `<div class="lc"><small>${lnE(S.tag)}</small><h3>${lnE(S.n)}</h3><p>${lnE(S.d)}</p><p class="lm">About ${lnRound(LNB[k].length).toLocaleString('en-US')} practice questions</p><div class="lk"><a class="lnb" href="/learn/${k}">Requirements</a><a class="lnb o" href="/learn/${k}/practice">Practice</a></div></div>`}).join('')}</div>`}
function lnReq(id){const S=LNS[id];return lnPills(id,'req')+lnTabs(id,'req')+S.req.map(r=>`<h2>${lnE(r[0])}</h2><ul>${r[1].map(x=>`<li>${lnE(x)}</li>`).join('')}</ul>`).join('')+`<h2>Selection stages</h2><ol>${S.steps.map(s=>`<li><b>${lnE(s[0])}</b>${lnE(s[1])}</li>`).join('')}</ol><p class="lm">${lnE(S.stepNote)}</p><h2>How to prepare</h2><ul>${S.prep.map(x=>`<li>${lnE(x)}</li>`).join('')}</ul><p style="margin-top:18px"><a class="lnb" href="/learn/${id}/practice">Start practice questions</a></p><p class="lm" style="margin-top:18px">Rules change and can differ by role. Check the current rules with the official recruiter before you apply.</p>`}
function lnPractice(id,cat){
 const ci=cat?lnCatIx(cat):-1,S=LNS[id],base='/learn/'+id+'/practice';LNST={id,cat:ci,len:20,qs:[],i:0,score:0,ans:null,miss:[],by:{}};
 const pool=lnPool(id,ci<0?null:ci),samples=lnSpread(pool,8);
 return lnPills(id,'practice')+lnTabs(id,'practice')+`<div id="ln-run">${lnSetup()}</div>`+
 `<div id="ln-samp"><h2>${ci<0?'Sample questions and answers':lnE(LNC[ci][1])+': sample questions and answers'}</h2>`+samples.map(q=>`<details><summary>${lnE(q[1])}</summary><p><b>Answer:</b> ${lnE(q[2])}</p><p>${lnE(q[4])}</p></details>`).join('')+`</div>`+
 `<h2>Practice by topic</h2><ul>${LNC.map((c,i)=>`<li><a href="${base}/${c[0]}">${lnE(S.n+' '+c[1].toLowerCase())}</a> (${lnPool(id,i).length} questions)</li>`).join('')}</ul><p><a href="/learn/${id}">${lnE(S.n)} requirements and selection stages</a></p><p class="lm">This is independent practice material. It is not an official test.</p>`}
function lnSetup(){const T=LNST,base='/learn/'+T.id+'/practice',pool=lnPool(T.id,T.cat<0?null:T.cat).length,n=Math.min(T.len,pool);
 return `<div class="ls"><b>Topic</b><div class="lp"><a href="${base}" class="${T.cat<0?'on':''}">All topics</a>${LNC.map((c,i)=>`<a href="${base}/${c[0]}" class="${T.cat===i?'on':''}">${lnE(c[1])}</a>`).join('')}</div></div>
 <div class="ls"><b>Number of questions</b><div class="lp">${[10,20,50].map(x=>`<button type="button" data-ln="len" data-v="${x}" class="${T.len===x?'on':''}"${x>pool&&pool<10?' disabled':''}>${x}</button>`).join('')}</div></div>
 <p><button type="button" class="lnb" data-ln="start">Start ${n} questions</button></p>`}
function lnBuild(){const T=LNST,n=T.len;let qs;
 if(T.cat>=0)qs=lnPick(lnPool(T.id,T.cat),n);
 else{const w=[.15,.4,.25,.2];qs=[];LNC.forEach((c,i)=>{qs=qs.concat(lnPick(lnPool(T.id,i),Math.min(Math.round(n*w[i]),lnPool(T.id,i).length)))});
  const have=new Set(qs);const rest=lnSh(LNB[T.id].filter(q=>!have.has(q)&&q[0]!==3&&q[0]!==0));while(qs.length<n&&rest.length)qs.push(rest.pop());qs=lnSh(qs).slice(0,n)}
 T.qs=qs.map(q=>({c:q[0],q:q[1],a:q[2],e:q[4],o:lnSh([q[2]].concat(q[3]))}));T.i=0;T.score=0;T.ans=null;T.miss=[];T.by={}}
function lnQ(){const T=LNST,q=T.qs[T.i],pc=Math.round(T.i/T.qs.length*100),L='ABCD';
 return `<div class="lr"><div class="lh"><span>Question ${T.i+1} of ${T.qs.length}</span><span>Score ${T.score}</span></div><div class="lnbar"><i style="width:${pc}%"></i></div><p class="lm">${lnE(LNC[q.c][1])}</p><p class="lnq">${lnE(q.q)}</p><div role="group" aria-label="Answers">${q.o.map((o,i)=>{let k='',m='';if(T.ans!=null){if(o===q.a){k=' ok';m='<em>✓ Correct</em>'}else if(o===T.ans){k=' no';m='<em>✗ Your answer</em>'}}return `<button type="button" class="lo${k}" data-ln="ans" data-v="${i}"${T.ans!=null?' disabled':''}>${m}<span>${L[i]}</span>${lnE(o)}</button>`}).join('')}</div>${T.ans!=null?`<div class="lx" role="status"><b>${T.ans===q.a?'Correct.':'Not quite. The answer is '+lnE(q.a)+'.'}</b><br>${lnE(q.e)}</div><p><button type="button" class="lnb" data-ln="next">${T.i+1<T.qs.length?'Next question':'See my score'}</button></p>`:''}</div>`}
function lnDone(){const T=LNST,n=T.qs.length,pc=Math.round(T.score/n*100);
 const by=Object.keys(T.by).map(c=>`<li>${lnE(LNC[c][1])}: ${T.by[c][0]} of ${T.by[c][1]}</li>`).join('');
 return `<div class="lr"><p class="lm">Your result</p><div class="lscore">${T.score} / ${n}</div><p><b>${pc}%</b></p>${by?`<ul>${by}</ul>`:''}${T.miss.length?`<h3>Questions to review</h3>${T.miss.map(m=>`<div class="lw"><b>${lnE(m.q)}</b><br>Your answer: ${lnE(m.y)}<br>Correct answer: ${lnE(m.a)}<br><span class="lm">${lnE(m.e)}</span></div>`).join('')}`:'<p>You answered every question correctly.</p>'}<p style="margin-top:14px"><button type="button" class="lnb" data-ln="again">Practise again</button> <button type="button" class="lnb o" data-ln="reset">Change topic or length</button></p></div>`}
let LNST={};
function lnDraw(){const r=document.getElementById('ln-run');if(!r)return;const T=LNST;r.innerHTML=!T.qs.length?lnSetup():T.i>=T.qs.length?lnDone():lnQ();const sp=document.getElementById('ln-samp');if(sp)sp.hidden=!!T.qs.length;if(T.qs.length&&T.ans!=null){const x=r.querySelector('.lx');if(x&&x.scrollIntoView)x.scrollIntoView({block:'nearest',behavior:'smooth'})}}
function lnClick(e){const b=e.target.closest&&e.target.closest('[data-ln]');if(!b||!document.getElementById('ln-run'))return;const T=LNST,a=b.dataset.ln;
 if(a==='len'){T.len=+b.dataset.v;lnDraw()}
 else if(a==='start'||a==='again'){lnBuild();lnDraw();const r=document.getElementById('ln-run');if(r&&r.scrollIntoView)r.scrollIntoView({block:'start'})}
 else if(a==='reset'){T.qs=[];lnDraw()}
 else if(a==='ans'&&T.ans==null){const q=T.qs[T.i],o=q.o[+b.dataset.v];T.ans=o;const g=T.by[q.c]||(T.by[q.c]=[0,0]);g[1]++;if(o===q.a){T.score++;g[0]++}else T.miss.push({q:q.q,y:o,a:q.a,e:q.e});lnDraw()}
 else if(a==='next'&&T.ans!=null){T.i++;T.ans=null;lnDraw();const r=document.getElementById('ln-run');if(r&&r.scrollIntoView)r.scrollIntoView({block:'start'})}}
let LNH=0;
function lnInit(){lnStyle();if(!LNH){LNH=1;document.addEventListener('click',lnClick)}}
function lnPg(p){lnStyle();const id=lnSel(p);let inner;
 if(!p[1])inner=lnHub();
 else if(!id)inner=lnHub();
 else if(!p[2])inner=lnReq(id);
 else if(p[2]==='practice'&&(!p[3]||lnCatIx(p[3])>=0)&&!p[4])inner=lnPractice(id,p[3]);
 else inner=lnHub();
 return `<section class="lns" id="learn">${inner}</section>`}
